'use strict';
state.receipts??=[];state.aliases??={};
labels.expenses=['◷','Chi tiêu'];
let receiptDraft=null,receiptPhoto=null,receiptPhotoURL='',notesDraft=null,ocrBusy=false;
function spendingSummary(start){const receipts=receiptsInWeek(state,start).filter(r=>(r.currency||'AUD')===currentCurrency(state));const actual=receipts.reduce((n,r)=>n+receiptTotal(r),0);return{receipts,actual,remaining:state.preferences.budget-actual}}
// v1.7.19 audit C15: discount, adjustment and other non-item lines are part of the bill, not spending still to match
function receiptLineOpen(i){return !i.ingredient&&!i.recipe&&i.kind!=='other'&&(!i.lineKind||i.lineKind==='item')}
function renderExpenses(){const {receipts,actual,remaining}=spendingSummary(weekStart),history=priceHistory(state).filter(h=>h.currency===currentCurrency(state));const unallocated=receipts.reduce((n,r)=>n+Math.abs(r.total-r.items.reduce((m,i)=>m+i.total,0))+r.items.filter(receiptLineOpen).reduce((m,i)=>m+Math.abs(i.total),0),0);return heading('Chi tiêu, rõ ràng hơn','Từ hóa đơn đi chợ đến ngân sách và giá từng nguyên liệu.',`<button class="btn primary" data-feature="receipt-new">▧ Chụp / nhập hóa đơn</button>`)+`<div class="week-tools">${weekControls()}<div class="toolbar"><button class="btn small" data-feature="notes-import">▤ Nhập ghi chú</button><button class="btn small" data-feature="cloud-settings">☁ Đồng bộ gia đình</button></div></div><div class="stat-grid"><div class="card"><small>ĐÃ CHI THỰC TẾ</small><strong>${aud(actual)}</strong><small>${receipts.length} hóa đơn trong tuần</small></div><div class="card"><small>${remaining>=0?'CÒN TRONG NGÂN SÁCH':'VƯỢT NGÂN SÁCH'}</small><strong style="color:${remaining<0?'#ad6542':'inherit'}">${aud(Math.abs(remaining))}</strong><small>Mục tiêu ${aud(state.preferences.budget)}</small></div><div class="card"><small>CHƯA ĐỐI ỨNG / PHÂN BỔ</small><strong>${aud(unallocated)}</strong><small>Dòng chưa rõ + chênh tổng bill</small></div></div><div class="shopping-layout"><section><div class="section-heading"><h2>Hóa đơn tuần này</h2><small>Ngày mua quyết định tuần ghi nhận</small></div>${receipts.length?receipts.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<article class="card receipt-card"><div><span class="receipt-symbol">▧</span><h3>${esc(r.store||tr('Cửa hàng chưa đặt tên','Unnamed store'))}</h3><small>${(()=>{const n=r.items.length,u=r.items.filter(receiptLineOpen).length;return dateLabel(r.date)+' · '+tr(`${n} dòng · ${u} chưa đối ứng`,`${n} line${n===1?'':'s'} · ${u} not matched`)})()}</small></div><div class="receipt-total"><b>${aud(r.total)}</b><button class="text-btn" data-feature="receipt-open" data-id="${r.id}">Xem / sửa ↗</button></div></article>`).join(''):'<div class="card empty"><span class="emoji">🧾</span><h3>Chưa có hóa đơn trong tuần</h3><p>Chụp bill hoặc dán nội dung để ghi khoản chi đầu tiên.</p><button class="btn primary" data-feature="receipt-new">Chụp / nhập hóa đơn</button></div>'}<div class="section-heading"><h2>Giá nguyên liệu có tăng không?</h2><span class="pill gray">Giá thực mua / kg, lít, quả</span></div><div class="card">${history.length?history.map(h=>`<div class="price-history-row"><div><b>${esc(INGREDIENTS[h.ingredient][0])}</b><small>${esc(h.store||tr('Chưa rõ cửa hàng','Store not known'))} · ${dateLabel(h.date)} · ${tr(`${h.count} lần ghi nhận`,`${h.count} recorded purchase${h.count===1?'':'s'}`)}</small><small>${esc(h.label)}</small></div><div><b>${aud(h.value)} / ${h.unit}</b><span class="pill ${h.change>0?'orange':'gray'}">${h.change===null?tr('Cần thêm 1 lần mua','Needs one more purchase'):(h.change>0?'↑ ':h.change<0?'↓ ':'= ')+Math.abs(h.change).toFixed(1)+'%'}</span></div></div>`).join(''):'<p class="hint">Nhập khối lượng thực mua trên hóa đơn để so sánh đơn giá. Không suy ra giá/kg từ một gói chưa rõ trọng lượng.</p>'}<p class="hint topspace">So sánh hai lần mua gần nhất của cùng nguyên liệu tại cùng cửa hàng, theo dữ liệu bạn xác nhận. Quy cách, nhãn hàng và khuyến mãi có thể khác nhau; đây là biến động giá ghi nhận, không phải chỉ số lạm phát.</p></div></section><aside class="card budget-card"><h3>Bốn tuần gần đây</h3>${[3,2,1,0].map(n=>{const start=addDays(weekStart,-7*n),sum=spendingSummary(start).actual,width=Math.min(100,sum/state.preferences.budget*100);return `<div class="spend-week"><div><span>${dateLabel(start)} – ${dateLabel(addDays(start,6))}</span><b>${aud(sum)}</b></div><div class="progress"><span style="width:${width}%;background:${sum>state.preferences.budget?'#c58b58':'#55845e'}"></span></div></div>`}).join('')}<p>Chi thực tế lấy từ tổng hóa đơn. Danh sách đi chợ vẫn là dự toán riêng, không cộng chồng vào chi thực tế.</p>${/* v1.7.19 (audit A20): one label for the receipt sheet; not repeated next to the empty card */receipts.length?'<button class="btn full" data-feature="receipt-new">Chụp / nhập hóa đơn</button>':''}</aside></div>`}
function matchingOptions(match){const[start,end]=shopDates(),needed=shopping(state,currentWeek(),start,end).filter(r=>shoppingHasAmount(r)&&!r.skip).map(r=>r.id);const planned=[...new Map(Object.values(currentWeek().days).flatMap(day=>Object.values(day).flatMap(m=>m.recipes)).map(r=>[r.id,r])).values()];const option=(id,name)=>`<option value="${esc(id)}" ${match===id?'selected':''}>${esc(name)}</option>`;const nm=id=>typeof shopIngName==='function'?shopIngName(id):INGREDIENTS[id][0];return option('',tr('Chưa đối ứng','Not matched'))+option('other',tr('Chi tiêu khác / không phải nguyên liệu','Other spending / not an ingredient'))+`<optgroup label="${tr('Nguyên liệu đang cần mua','Ingredients to buy')}">${needed.map(id=>option(id,nm(id))).join('')}</optgroup><optgroup label="${tr('Nguyên liệu khác','Other ingredients')}">${Object.entries(INGREDIENTS).filter(([id])=>!needed.includes(id)).map(([id,i])=>option(id,nm(id))).join('')}</optgroup><optgroup label="${tr('Món ăn trong thực đơn','Dishes on the menu')}">${planned.map(r=>option('recipe:'+r.id,r.name)).join('')}</optgroup>`}
function newReceipt(){receiptDraft={currency:currentCurrency(state),id:uid(),store:'',date:sydneyDate(),total:0,items:[],createdAt:new Date().toISOString(),editing:false};receiptPhoto=null;if(receiptPhotoURL)URL.revokeObjectURL(receiptPhotoURL);receiptPhotoURL='';receiptEditor()}
function receiptEditor(){const d=receiptDraft;if(!d)return;modal(d.editing?tr('Xem & sửa hóa đơn','View & edit receipt'):tr('Chụp / nhập hóa đơn','Snap / type a receipt'),`<div class="receipt-entry-tools"><button class="btn soft" data-feature="receipt-camera">▧ ${tr('Chụp hoá đơn','Snap receipt')}</button><button class="btn" data-feature="receipt-file">${tr('Chọn ảnh','Choose photo')}</button><select class="input" id="ocr-language" aria-label="${tr('Ngôn ngữ hóa đơn','Receipt language')}" style="width:auto"><option value="eng">${tr('Tiếng Anh','English')}</option><option value="eng+vie">${tr('Anh + Việt','English + Vietnamese')}</option></select></div><input type="file" id="receipt-camera-file" accept="image/*" capture="environment" hidden><input type="file" id="receipt-gallery-file" accept="image/*" hidden>${receiptPhotoURL?`<img class="receipt-image" src="${receiptPhotoURL}" alt="${tr('Ảnh hóa đơn đang đối chiếu','Receipt photo being checked')}">`:''}<p id="ocr-status" class="hint" role="status">${tr('Đọc chữ trên thiết bị; cần mạng để tải bộ OCR lần đầu. Kết quả là đề xuất, bạn kiểm tra trước khi lưu. Ảnh chưa được gửi đi tự động.','Text is read on this device; the reader downloads once (needs internet). Results are suggestions to check before saving. The photo is not sent anywhere.')}</p><div class="field"><label for="receipt-raw">${tr('Hoặc dán / sửa nội dung hóa đơn','Or paste / edit the receipt text')}</label><textarea id="receipt-raw" rows="5" placeholder="Chicken breast 500g 8.50&#10;Tomato 1kg 4.00&#10;TOTAL 12.50">${esc(d.raw||'')}</textarea></div><div class="toolbar"><button class="btn small" data-feature="receipt-parse">${tr('Đọc các dòng hóa đơn','Read the receipt lines')}</button><button class="text-btn" data-feature="receipt-add-line">+ ${tr('Nhập một dòng','Type a line')}</button></div><div class="form-grid topspace"><div class="field"><label for="receipt-store">${tr('Cửa hàng','Store')}</label><input id="receipt-store" maxlength="100" list="receipt-store-list" value="${esc(d.store)}" placeholder="${tr('Woolworths, Coles, chợ Việt…','Woolworths, Coles, Asian grocer…')}"><datalist id="receipt-store-list">${storeChoiceNames().map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist></div><div class="field"><label for="receipt-date">${tr('Ngày mua','Date bought')}</label><input id="receipt-date" type="date" value="${d.date}" required></div></div><div id="receipt-lines">${receiptLineRows()}</div><div class="receipt-reconcile"><div class="field"><label for="receipt-total">${tr('Tổng thực trả','Total paid')} (${d.currency||'AUD'})</label><input id="receipt-total" type="number" min="0" max="999999999" step="0.01" value="${d.total}" required></div><div><small>${tr('Tổng các dòng','Lines total')}</small><b id="receipt-lines-total"></b></div><div><small>${tr('Chưa phân bổ / điều chỉnh','Not assigned / adjustment')}</small><b id="receipt-difference"></b></div></div><p class="hint">${tr('Dòng giảm giá có thể nhập số tiền âm. Chênh lệch với tổng bill được giữ riêng; không tự sửa để trông khớp. Khối lượng không rõ có thể để trống, nhưng chưa so sánh được đơn giá.','Discount lines can be negative. A gap from the receipt total is kept separately, never adjusted to look right. An unknown weight can stay empty, but then the unit price cannot be compared.')}</p><label class="checked-label"><input id="receipt-mark-bought" type="checkbox" class="check" ${d.editing?'disabled':''}> ${tr('Đánh dấu đã mua theo khối lượng thực đã đối ứng','Mark as bought by the matched amounts')}</label><p class="hint">${tr('Chỉ áp dụng cho nguyên liệu trong phạm vi danh sách đang xem, có khối lượng hợp lệ. Chưa tự cộng tồn kho; bạn dùng “Cất đồ đã mua” ở tab Đi chợ.','Only for ingredients on the list in view with a valid amount. Nothing goes into the pantry yet; use “Put the shopping away” on Shopping.')}</p>`,`<button class="btn" data-feature="receipt-add-line">+ ${tr('Thêm dòng','Add line')}</button><button class="btn primary" data-feature="receipt-save">${d.editing?tr('Lưu chỉnh sửa','Save changes'):tr('Kiểm tra & lưu khoản chi','Check & save the expense')}</button>`,true);$('.modal').classList.add('receipt-modal');updateReceiptTotals()}
// v1.7.19 (owner, 12 Nov 2026, Sydney time: “Đổi cả 3 chỗ”, rule 29): a receipt line's unit and a notes-import line's unit are
// chosen in the shared unit picker, with suggestions for the matched ingredient and the family's own units. “gói / hộp chưa rõ
// lượng” stays available as its own choice. The value is stored as chosen; a family unit with a conversion is counted through it.
const RECEIPT_UNIT_LABELS=()=>({pack:tr('gói / hộp chưa rõ lượng','pack / box, amount unknown')});
if(typeof registerUnitRowField==='function'){
 registerUnitRowField('receipt-unit-',(inp:any)=>{const line=inp.closest('.receipt-line'),m=(line?.querySelector('.receipt-match') as any)?.value||'';return{ingredient:INGREDIENTS[m]?m:null,name:(line?.querySelector('.receipt-label') as any)?.value||'',title:tr('Đơn vị trên hoá đơn','Unit on the receipt'),defaults:['g','kg','ml','l','quả','gói','hộp','chai'],ownUnits:['pack'],ownTitle:tr('Chưa rõ lượng','Amount not known'),labels:RECEIPT_UNIT_LABELS()}});
 registerUnitRowField('note-unit-',(inp:any)=>{const row=inp.closest('.note-import-row'),m=(row?.querySelector('.note-match') as any)?.value||'',raw=notesDraft?.rows?.[+row?.dataset.index]?.raw||'';return{ingredient:INGREDIENTS[m]?m:null,name:INGREDIENTS[m]?INGREDIENTS[m][0]:raw,title:tr('Đơn vị trong ghi chú','Unit in the note'),defaults:['g','kg','ml','l','quả','gói','hộp','bó'],ownUnits:['pack'],ownTitle:tr('Chưa rõ lượng','Amount not known'),labels:RECEIPT_UNIT_LABELS()}})}
function receiptLineRows(){return receiptDraft.items.map((item,index)=>`<article class="receipt-line" data-index="${index}"><div class="receipt-line-top"><input class="input receipt-label" aria-label="${tr('Tên dòng','Line name')} ${index+1}" value="${esc(item.label)}" maxlength="200"><input class="input receipt-price" aria-label="${tr('Thành tiền dòng','Line amount')} ${index+1}" type="number" step="0.01" min="-999999999" max="999999999" value="${item.total}"><button class="icon" data-feature="receipt-remove-line" data-index="${index}" aria-label="${tr('Bỏ dòng','Remove line')} ${index+1}">×</button></div><div class="receipt-line-bottom"><div class="field"><label>${tr('Đối ứng','Matches')} ${item.confidence&&item.confidence!=='unknown'?tr('· đề xuất cần kiểm tra','· suggestion to check'):''}</label><select class="input receipt-match" aria-label="${tr('Đối ứng dòng','Match for line')} ${index+1}">${matchingOptions(item.match)}</select></div><div class="field"><label>${tr('Khối lượng thực','Actual amount')}</label><input class="input receipt-qty" aria-label="${tr('Khối lượng dòng','Amount of line')} ${index+1}" type="number" min="0.001" max="1000000" step="any" placeholder="${tr('Chưa rõ','Unknown')}" value="${item.qty??''}"></div><div class="field"><label>${tr('Đơn vị','Unit')}</label>${typeof unitFieldMarkup==='function'?unitFieldMarkup({id:`receipt-unit-${index}`,value:item.unit||'',cls:'receipt-unit',label:`${tr('Đơn vị dòng','Unit of line')} ${index+1}`,labels:RECEIPT_UNIT_LABELS()}):`<select class="input receipt-unit" aria-label="${tr('Đơn vị dòng','Unit of line')} ${index+1}">${[['',tr('Chưa rõ','Unknown')],['g','g'],['kg','kg'],['ml','ml'],['l',tr('lít','L')],['quả',tr('quả','each')],...[...(typeof BUYING_UNITS!=='undefined'?BUYING_UNITS:[]),...new Set(Object.values(state.purchaseUnitPreferences||{}).map(p=>p.unit))].filter(u=>!['g','kg','ml','l','quả'].includes(u)).map(u=>[u,u]),['pack',tr('gói / hộp chưa rõ lượng','pack / box, amount unknown')]].map(([u,n])=>`<option value="${u}" ${item.unit===u?'selected':''}>${n}</option>`).join('')}</select>`}</div></div></article>`).join('')||`<div class="empty"><p>${tr('Chọn ảnh hoặc dán nội dung, sau đó bấm “Đọc các dòng hóa đơn”.','Choose a photo or paste the text, then tap “Read the receipt lines”.')}</p></div>`}
function collectReceipt(){if(!receiptDraft||!$('#receipt-store'))return;receiptDraft.store=$('#receipt-store').value.trim();receiptDraft.date=$('#receipt-date').value;receiptDraft.total=+$('#receipt-total').value;receiptDraft.raw=$('#receipt-raw').value;receiptDraft.markBought=$('#receipt-mark-bought')?.checked||false;$$('.receipt-line').forEach(el=>{const item=receiptDraft.items[+el.dataset.index];item.label=$('.receipt-label',el).value.trim();item.total=+$('.receipt-price',el).value;item.match=$('.receipt-match',el).value;item.qty=$('.receipt-qty',el).value===''?null:+$('.receipt-qty',el).value;item.unit=$('.receipt-unit',el).value})}
function updateReceiptTotals(){if(!receiptDraft||!$('#receipt-lines-total'))return;collectReceipt();const sum=receiptDraft.items.reduce((n,i)=>n+i.total,0);$('#receipt-lines-total').textContent=aud(sum,receiptDraft.currency);$('#receipt-difference').textContent=aud(receiptDraft.total-sum,receiptDraft.currency)}
let ocrScriptPromise=null;
function loadOCR(){if(window.Tesseract)return Promise.resolve();if(!ocrScriptPromise)ocrScriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.0.0/dist/tesseract.min.js';script.onload=resolve;script.onerror=()=>{ocrScriptPromise=null;reject(Error('Không tải được OCR. Hãy thử lại khi có mạng hoặc dán nội dung hóa đơn.'))};document.head.append(script)});return ocrScriptPromise}
async function photoBlob(file){if(file.size>20000000)throw Error('Ảnh tối đa 20 MB. Hãy chụp lại gần và rõ nét.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,1800/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Không đọc được ảnh. Dùng JPEG hoặc PNG.')),'image/jpeg',.88))}finally{URL.revokeObjectURL(url)}}
async function readReceiptPhoto(file){if(!file||ocrBusy)return;if((!navigator.onLine||globalThis.BEP_OFFLINE)&&!(typeof ocrOfflineReady==='function'&&ocrOfflineReady())){try{collectReceipt();receiptPhoto=await photoBlob(file);if(receiptPhotoURL)URL.revokeObjectURL(receiptPhotoURL);receiptPhotoURL=URL.createObjectURL(receiptPhoto);receiptEditor();$('#ocr-status').textContent='Đang offline: ảnh được giữ trên máy. Nhập dòng và tổng tiền bằng tay; đọc chữ OCR cần mạng để tải bộ nhận dạng.'}catch{toast('Chưa giữ được ảnh. Có thể nhập khoản chi bằng tay.',true)}return}collectReceipt();const lang=$('#ocr-language')?.value||'eng';ocrBusy=true;let worker;const status=text=>{if($('#ocr-status'))$('#ocr-status').textContent=text};try{receiptPhoto=await photoBlob(file);if(receiptPhotoURL)URL.revokeObjectURL(receiptPhotoURL);receiptPhotoURL=URL.createObjectURL(receiptPhoto);status('Đang tải bộ đọc hóa đơn…');await loadOCR();worker=await Tesseract.createWorker(lang,1,{logger:info=>status(`${info.status==='recognizing text'?'Đang đọc chữ':info.status} · ${Math.round((info.progress||0)*100)}%`)});const result=await worker.recognize(receiptPhoto);receiptDraft.raw=result.data.text;const parsed=parseReceiptText(result.data.text,state);/* v1.7.19 (audit sweep, rule 36): a photo that reads no lines keeps the lines already confirmed */if(!parsed.items.length&&(receiptDraft.items||[]).length)toast(tr('Không đọc được dòng nào từ ảnh; các dòng đang có vẫn giữ nguyên.','No lines could be read from the photo; the lines already here stay as they are.'),true);else Object.assign(receiptDraft,{store:receiptDraft.store||parsed.store,date:parsed.date,total:parsed.total,items:parsed.items});receiptEditor();status(`Đã đọc ảnh · độ tin cậy OCR trung bình ${Math.round(result.data.confidence||0)}%. Kiểm tra tên, khối lượng, ngày và tổng tiền trước khi lưu.`)}catch(error){toast(error.message||'Chưa đọc được ảnh. Bạn có thể dán chữ hoặc nhập thủ công.',true);status('OCR chưa hoàn tất. Không có khoản chi nào được tự ghi nhận.')}finally{ocrBusy=false;if(worker)await worker.terminate()}}
function photoDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('bep-receipt-photos'+(storageScope?'-'+storageScope.replace(/[^a-z0-9-]/gi,'_'):''),1);request.onupgradeneeded=()=>request.result.createObjectStore('photos');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function localPhoto(id,value){const db=await photoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('photos',value===undefined?'readonly':'readwrite'),store=tx.objectStore('photos');const r=value===undefined?store.get(id):store.put(value,id);let result;r.onsuccess=()=>result=r.result;tx.oncomplete=()=>{db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)}})}
