function syncApplyState(next,etag,remote){next=clone(next);// merged results share objects with their inputs
 if(!validImport(next))throw Object.assign(Error('merge-invalid'),{code:'merge-invalid'});upgradeReferenceCatalog(next,state?.deletedRecipeIds);next.receipts??=[];next.aliases??={};ensureWeek(next,monday(weekStart));state=next;familyStorage.setItem(KEY,JSON.stringify(state));if(typeof activatePrices==='function')activatePrices(state);unsaved=false;cloudConnection.etag=etag;if(remote)setSyncBase(etag,remote);syncPrev=clone(state);syncRender()}
function syncRender(){const a=document.activeElement;if(a&&a.closest?.('#main')&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)){if(!syncRender.waiting){syncRender.waiting=true;a.addEventListener('blur',()=>{syncRender.waiting=false;setTimeout(()=>{try{render()}catch{}},0)},{once:true})}return}try{render()}catch(e){console.warn('render after sync',e?.message)}}
function syncScheduleRetry(ms){clearTimeout(cloudConnection.timer);cloudConnection.timer=setTimeout(()=>syncFamilyState(),ms)}
function queueFamilySync() {if(globalThis.BEP_SESSION?.mode!=='account'||!globalThis.BEP_SESSION.household)return;if(typeof syncStampLocal==='function'){cloudConnection.editAt=Date.now();clearTimeout(syncStampLocal.t);syncStampLocal.t=setTimeout(syncStampLocal,1000)}cloudConnection.dirty=true;if(!cloudConnection.connected){if(familyStorage.getItem('bep-cloud-enabled')==='yes')familyStorage.setItem('bep-cloud-pending','yes');return}familyStorage.setItem('bep-cloud-pending','yes');clearTimeout(cloudConnection.timer);cloudConnection.timer=setTimeout(()=>syncFamilyState(),1200);setTimeout(updateCloudStatus,0)}
// Push: debounced ~1.2 s (immediately for alerts and "bought"). A stale write is merged and retried automatically
// (bounded, with jitter); the review dialog remains only for a state this app cannot read (newer edition, invalid merge).
async function syncFamilyState(){if(cloudConnection.newerEdition||!cloudConnection.connected||cloudConnection.syncing||cloudConnection.conflict||!cloudConnection.dirty||!navigator.onLine)return;cloudConnection.syncing=true;setTimeout(updateCloudStatus,0);let retry=0;try{await loadSyncBase();syncStampLocal();
 const out=await syncPushLoop({local:()=>state,etag:()=>cloudConnection.etag,base:syncMergeBase,
  put:async body=>{const res=await familyRequest('state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return{status:res.status,data:await res.json().catch(()=>null)}},
  fetchRemote:fetchFamilyState,blocked:remote=>newerEditionState(remote?.state),
  apply:({state:next,etag,remote})=>{if(!remote){cloudConnection.etag=etag;setSyncBase(null,null);return}syncApplyState(next,etag,remote)},
  synced:({etag,sent})=>{cloudConnection.etag=etag;setSyncBase(etag,sent)},
  sleep:ms=>new Promise(r=>setTimeout(r,ms)),random:Math.random});
 if(out.ok){cloudConnection.dirty=!syncEq(state,cloudConnection.base);if(!cloudConnection.dirty)familyStorage.removeItem('bep-cloud-pending');cloudConnection.lastSyncAt=Date.now();if(out.merged){cloudConnection.mergedAt=Date.now();cloudConnection.merges++;setTimeout(updateCloudStatus,SYNC_MERGED_MS+50)}if(typeof syncNotify==='function')syncNotify(out);uploadPendingPhotos();if(cloudConnection.dirty)retry=1000;return}
 if(out.reason==='blocked'){showNewerEditionNotice();return}
 if(out.status===401){cloudConnection.connected=false;toast('Phiên Đồng bộ gia đình hết hạn. Kết nối lại để tiếp tục đồng bộ.',true);return}
 if(out.status===423)return;
 // Still clashing after the bounded retries (very busy family) or refused: keep everything here and try again shortly.
 if(out.reason==='retries'||out.reason==='would_drop'){retry=4000+Math.round(Math.random()*4000);if(out.merged&&typeof syncNotify==='function')syncNotify(out);return}
 throw Error('Đồng bộ chưa lưu được dữ liệu.')}catch(error){if(error?.code==='merge-invalid'){cloudConnection.conflict=true;await loadRemoteConflict();return}toast('Đã giữ dữ liệu trên máy; đang chờ lưu trực tuyến.',true)}finally{cloudConnection.syncing=false;updateCloudStatus();if(retry&&!cloudConnection.conflict)syncScheduleRetry(retry)}}
// Pull before push: a cheap version check, then the full copy only when it changed; merged into this device's copy.
async function syncPull(){if(cloudConnection.newerEdition||!cloudConnection.connected||cloudConnection.syncing||cloudConnection.pulling||cloudConnection.conflict||cloudConnection.checking||!navigator.onLine||globalThis.BEP_OFFLINE)return false;cloudConnection.pulling=true;try{
 const v=await familyRequest('state-version');if(v.ok){const d=await v.json().catch(()=>null);if(d&&d.etag===cloudConnection.etag){if(cloudConnection.dirty&&!cloudConnection.syncing)syncFamilyState();return false}}
 const remote=await fetchFamilyState();if(!remote?.state||remote.etag===cloudConnection.etag)return false;
 if(newerEditionState(remote.state)){showNewerEditionNotice();return false}
 await loadSyncBase();if(cloudConnection.syncing||cloudConnection.conflict)return false;
 syncStampLocal();const base=syncMergeBase(),clean=!cloudConnection.dirty&&!!base&&syncEq(state,base);
 const report=mergeFamilyStates(base,state,remote.state);syncApplyState(report.state,remote.etag,remote.state);
 cloudConnection.lastSyncAt=Date.now();if(!clean&&report.changedLocal&&report.changedRemote){cloudConnection.mergedAt=Date.now();cloudConnection.merges++;setTimeout(updateCloudStatus,SYNC_MERGED_MS+50)}
 if(report.changedRemote){cloudConnection.dirty=true;familyStorage.setItem('bep-cloud-pending','yes');syncScheduleRetry(300)}else{cloudConnection.dirty=false;familyStorage.removeItem('bep-cloud-pending')}
 if(typeof syncNotify==='function')syncNotify({merged:!clean&&report.changedRemote?1:0,conflicts:report.conflicts,notes:report.notes,pulled:true});return true}
 catch(error){if(error?.code==='merge-invalid'){cloudConnection.conflict=true;await loadRemoteConflict()}return false}finally{cloudConnection.pulling=false;updateCloudStatus()}}
function syncSoon(){if(!cloudConnection.connected)return;if(cloudConnection.dirty&&!cloudConnection.syncing)syncFamilyState();else syncPull()}
// A newer app edition wrote the shared state: stop syncing (never offer "keep this device's copy") and reload into the new code.
function newerEditionState(data){return !!data&&typeof data==='object'&&stateEdition(data)>APP_EDITION}
function showNewerEditionNotice(){const copy=(vi,en)=>typeof tr==='function'?tr(vi,en):vi;cloudConnection.newerEdition=true;let auto=false;try{const key='bep-edition-reload';if(sessionStorage.getItem(key)!==String(APP_EDITION)){sessionStorage.setItem(key,String(APP_EDITION));auto=true}}catch{}modal(copy('Có bản cập nhật — tải lại','Update available — reload'),`<p>${copy('Dữ liệu gia đình vừa được lưu bằng phiên bản app mới hơn. Thiết bị này đã tạm dừng đồng bộ để không ghi đè thay đổi của người khác.','Your family data was saved by a newer version of the app. This device has paused syncing so it cannot overwrite anyone else’s changes.')}</p><div class="callout">${copy('Tải lại để dùng phiên bản mới. Dữ liệu trên máy này vẫn được giữ.','Reload to use the new version. Data on this device is kept.')}</div>`,`<button class="btn primary" data-feature="reload-app">${copy('Tải lại ngay','Reload now')}</button>`,true);if(auto&&navigator.onLine)setTimeout(()=>location.reload(),1500)}
function persistRemoteState(data){if(newerEditionState(data)){showNewerEditionNotice();throw Error(typeof tr==='function'?tr('Có bản cập nhật — tải lại','Update available — reload'):'Có bản cập nhật — tải lại')}if(!validImport(data))throw Error('Dữ liệu Đồng bộ không đúng định dạng.');upgradeReferenceCatalog(data,state?.deletedRecipeIds);state=data;state.receipts??=[];state.aliases??={};ensureWeek(state,monday(weekStart));familyStorage.setItem(KEY,JSON.stringify(state));if(typeof activatePrices==='function')activatePrices(state);unsaved=false;cloudConnection.dirty=false;syncPrev=clone(state);render();updateCloudStatus()}
async function fetchFamilyState(){const res=await familyRequest('state');if(!res.ok)throw Error('Không tải được bản trực tuyến.');return res.json()}
async function loadRemoteConflict(){try{const remote=await fetchFamilyState();cloudConnection.remote=remote;if(newerEditionState(remote?.state)){showNewerEditionNotice();return}modal('Hai thiết bị vừa thay đổi dữ liệu',`<p>App đã dừng đồng bộ để tránh ghi đè thay đổi của người khác.</p><div class="callout">Bạn có thể xuất bản đang có trên máy để giữ lại, rồi chọn dùng bản trực tuyến hoặc thay bằng bản trên máy này. Không tự gộp những chỉnh sửa mâu thuẫn.</div>`,`<button class="btn" data-action="export">Xuất bản máy này</button><button class="btn" data-feature="cloud-use-remote">Dùng bản trực tuyến</button><button class="btn primary" data-feature="cloud-use-local">Dùng bản máy này</button>`,true)}catch(e){toast('Có xung đột; cần mạng để đối chiếu bản trực tuyến.',true)}}
async function cloudSettings(){modal('Đồng bộ gia đình',`<p>${cloudConnection.connected?'Dữ liệu đang kết nối với gia đình của tài khoản.':'Đăng nhập bằng tài khoản cá nhân để kết nối dữ liệu gia đình.'}</p>`,`<a class="btn primary" href="/login?locked=1">Tài khoản</a>`,true)}
async function uploadPendingPhotos(){if(!cloudConnection.connected||cloudConnection.photoBusy)return;cloudConnection.photoBusy=true;try{for(const r of state.receipts){if(!r.hasPhoto)continue;const local=await localPhoto(r.id);if(!local?.blob||local.uploaded)continue;const res=await familyRequest('photo&id='+encodeURIComponent(r.id),{method:'PUT',headers:{'Content-Type':'image/jpeg'},body:local.blob});if(res.status===423)return;if(!res.ok)throw Error('Ảnh chưa tải trực tuyến.');await localPhoto(r.id,{...local,uploaded:true})}}catch(error){toast('Khoản chi đã lưu; ảnh receipt còn trên máy và sẽ tải lại sau.',true)}finally{cloudConnection.photoBusy=false}}
async function checkCloud(){if(globalThis.BEP_SESSION?.mode!=='account'||!globalThis.BEP_SESSION.household)return;if(cloudConnection.checking)return;cloudConnection.checking=true;try{const res=await familyRequest('status');if(!res.ok||!res.headers.get('content-type')?.includes('application/json'))return;const data=await res.json(),wasLinked=cloudConnection.connected&&!!cloudConnection.etag;cloudConnection.available=true;cloudConnection.configured=!!data.configured;cloudConnection.connected=!!data.connected;if(data.mode==='account'&&!data.household){cloudConnection.connected=false;return}// v1.7.3: a re-check while this device is already linked (network recovered) never adopts the stored etag without a
 // merge (that would let a later push overwrite another device's change): it pulls/pushes through the merge instead.
 if(data.connected&&wasLinked){setTimeout(()=>syncSoon(),0);return}
 if(data.connected){const remote=await fetchFamilyState();cloudConnection.etag=remote.etag;const firstLink=familyStorage.getItem('bep-cloud-enabled')!=='yes',pending=familyStorage.getItem('bep-cloud-pending')==='yes'||remote.state&&familyStorage.getItem('bep-cloud-enabled')!=='yes'&&(state.recipes.some(r=>r.custom&&JSON.stringify(r)!==JSON.stringify(remote.state.recipes?.find(x=>x.id===r.id)))||state.receipts.some(r=>!remote.state.receipts?.some(x=>x.id===r.id))||state.activity.length>0);familyStorage.setItem('bep-cloud-enabled','yes');if(pending){cloudConnection.dirty=true;cloudConnection.conflict=false;if(!remote.state||familyStorage.getItem('bep-cloud-base-etag')===remote.etag){await syncFamilyState()}else if(newerEditionState(remote.state)){showNewerEditionNotice()}else if(firstLink||!familyStorage.getItem('bep-cloud-base-etag')){cloudConnection.conflict=true;cloudConnection.remote=remote;await loadRemoteConflict()}else{cloudConnection.etag=familyStorage.getItem('bep-cloud-base-etag');await syncFamilyState()}}else if(remote.state){persistRemoteState(remote.state);setSyncBase(remote.etag,remote.state)}else{cloudConnection.dirty=true;await syncFamilyState()}}}catch(error){}finally{cloudConnection.checking=false;updateCloudStatus()}}
// Keep only a pending marker locally; the password stays in an HttpOnly session cookie.
window.addEventListener('pagehide',()=>{if(cloudConnection.editAt)syncStampLocal()});
window.addEventListener('beforeunload',()=>{if(cloudConnection.editAt)syncStampLocal();if(cloudConnection.dirty)familyStorage.setItem('bep-cloud-pending','yes');else if(cloudConnection.connected)familyStorage.removeItem('bep-cloud-pending')});
window.addEventListener('online',()=>{if(!cloudConnection.connected)checkCloud();else{syncSoon();uploadPendingPhotos()}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncSoon()});window.addEventListener('focus',()=>syncSoon());
// Every ~15 s while visible and idle: pull (etag check first). A pending write is retried by its own timer.
setInterval(()=>{if(document.hidden||cloudConnection.syncing||cloudConnection.pulling)return;if(cloudConnection.dirty){syncFamilyState();return}syncPull()},SYNC_PULL_MS);
document.addEventListener('click',async event=>{const el=event.target.closest('[data-feature]');if(!el||el.disabled)return;const action=el.dataset.feature,id=el.dataset.id;try{switch(action){case'receipt-new':newReceipt();break;case'receipt-open':await openReceipt(id);break;case'receipt-camera':$('#receipt-camera-file').click();break;case'receipt-file':$('#receipt-gallery-file').click();break;case'receipt-parse':{collectReceipt();/* v1.7.19 (audit sweep): never wipe confirmed lines — nothing to read, or nothing read, keeps them */if(!String(receiptDraft.raw||'').trim()){toast(tr('Chưa có chữ hóa đơn để đọc. Dán hoặc gõ các dòng vào ô phía trên trước; các dòng đang có vẫn giữ nguyên.','There is no receipt text to read yet. Paste or type the lines in the box above first; the lines already here stay as they are.'),true);break}const parsed=parseReceiptText(receiptDraft.raw,state);if(!parsed.items.length&&(receiptDraft.items||[]).length){toast(tr('Không đọc được dòng nào từ chữ này; các dòng đang có vẫn giữ nguyên.','No lines could be read from this text; the lines already here stay as they are.'),true);break}receiptDraft.items=parsed.items;receiptDraft.total=parsed.total;receiptDraft.date=parsed.date;receiptDraft.store=receiptDraft.store||parsed.store;receiptEditor();break}case'receipt-add-line':collectReceipt();receiptDraft.items.push({id:uid(),label:'',total:0,match:'',qty:null,unit:'',confidence:'unknown'});$('#receipt-lines').innerHTML=receiptLineRows();updateReceiptTotals();break;case'receipt-remove-line':collectReceipt();receiptDraft.items.splice(+el.dataset.index,1);$('#receipt-lines').innerHTML=receiptLineRows();updateReceiptTotals();break;case'receipt-save':await saveReceipt();break;case'receipt-save-confirm':await saveReceipt(true);break;case'receipt-back':receiptEditor();break;case'notes-import':notesImporter();break;case'notes-file':$('#notes-file-input').click();break;case'notes-preview':notesPreview();break;case'notes-apply':applyNotes();break;case'notes-back':notesImporter(notesDraft.text);break;case'manage-members':manageMembers();break;case'cloud-settings':await cloudSettings();break;case'cloud-use-remote':{const remote=cloudConnection.remote;if(remote?.state){persistRemoteState(remote.state);cloudConnection.etag=remote.etag;setSyncBase(remote.etag,remote.state);cloudConnection.conflict=false;cloudConnection.remote=null;familyStorage.removeItem('bep-cloud-pending');closeModal();toast('Đang dùng bản trực tuyến.')}break}case'reload-app':location.reload();break;case'cloud-use-local':{if(cloudConnection.newerEdition||newerEditionState(cloudConnection.remote?.state)){showNewerEditionNotice();break}cloudConnection.etag=cloudConnection.remote?.etag||null;cloudConnection.remote=null;cloudConnection.conflict=false;cloudConnection.dirty=true;closeModal();await syncFamilyState();break}case'cloud-sync':if(cloudConnection.conflict)await loadRemoteConflict();else{cloudConnection.dirty=true;await syncFamilyState();cloudSettings()}break;case'cloud-disconnect':await familyRequest('logout',{method:'POST'});cloudConnection.connected=false;clearTimeout(cloudConnection.timer);familyStorage.removeItem('bep-cloud-pending');familyStorage.removeItem('bep-cloud-enabled');updateCloudStatus();cloudSettings();break}}catch(error){toast(error.message||'Chưa thực hiện được thao tác. Hãy thử lại.',true)}});
document.addEventListener('input',e=>{if(e.target.matches('.receipt-price,#receipt-total'))updateReceiptTotals()});
document.addEventListener('change',async e=>{if(['receipt-camera-file','receipt-gallery-file'].includes(e.target.id))await readReceiptPhoto(e.target.files[0]);if(e.target.id==='notes-file-input'){const file=e.target.files[0];if(!file)return;if(file.size>1000000){toast('Tệp ghi chú tối đa 1 MB.',true);return}$('#notes-text').value=await file.text()}});
async function consumeSharedNotes(){if(location.hash!=='#import-notes'||!('caches'in window))return;try{const cache=await caches.open('bep-note-inbox');const res=await cache.match('/shared-notes-draft?scope='+encodeURIComponent(storageScope));if(res){const data=await res.json();await cache.delete('/shared-notes-draft?scope='+encodeURIComponent(storageScope));notesImporter([data.title,data.text].filter(Boolean).join('\n'))}}catch(error){toast('Chưa đọc được ghi chú chia sẻ. Bạn có thể dán trực tiếp.',true)}}
view=hashView()||view;{const d=typeof openHashDate==='function'?openHashDate():null;render();if(d)showHashDate(d)}const initialCloudCheck=checkCloud();consumeSharedNotes();
